LEFT = [
    '',
    '0101010', '0101010', '0000100', '1111110',
    '0000100', '1111110', '0000000', '1111111',
    '0000000', '1111111', '0000000', '1111111',
    '0000000', '1111111',
]
RIGHT = [
    '',
    '010101010101', '010101010101', '000101010101', '111101010101',
    '000001010101', '111111010101', '000000101010', '111111110101',
    '000000000101', '111111111101', '000000000001', '111111111111',
    '000000000000', '111111111111',
]

def transform(grid):
    h, w = len(grid), len(grid[0])
    hr = next((r for r, row in enumerate(grid) if all(v == 3 for v in row)), None)
    vc = next((c for c in range(w) if all(grid[r][c] == 3 for r in range(h))), None)
    if hr is None or vc is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        dr = abs(r - hr)
        for c in range(w):
            if r == hr or c == vc:
                out[r][c] = 3
            elif dr < len(LEFT):
                if c < vc:
                    d = vc - c
                    if d <= len(LEFT[dr]):
                        out[r][c] = 4 if LEFT[dr][d-1] == '1' else 0
                else:
                    d = c - vc
                    if d <= len(RIGHT[dr]):
                        out[r][c] = 4 if RIGHT[dr][d-1] == '1' else 0
    return out
